function show(id){$(id).showModal();}
function close(id){if(!busy)$(id).close();}
function groupCard(g,{preview=false}={}){const list=getGroup(g.id),c=counts(list),open=expanded===g.id;return `<article class="nxl-ag-group-card ${open?'is-expanded':''}" style="--group-color:${esc(g.color)}" data-group="${esc(g.id)}"><div class="nxl-ag-group-top"><button class="nxl-ag-group-open" ${preview?'disabled':''} data-open-group="${esc(g.id)}" aria-expanded="${open}" aria-label="Abrir grupo ${esc(g.name)}"><span class="nxl-ag-group-icon">${icon(g.icon)}</span><span><strong>${esc(g.name)}</strong><small>${c.total} ${c.total===1?'bem':'bens'}</small></span></button>${!g.reserved&&!preview&&canManage?`<button class="nxl-ag-icon-button nxl-ag-group-menu-trigger" data-group-menu="${esc(g.id)}" aria-label="Opções do grupo ${esc(g.name)}" aria-expanded="false">${icon('more')}</button><div class="nxl-ag-group-menu" role="menu" hidden><button role="menuitem" data-edit-group="${esc(g.id)}">${icon('edit')}Editar grupo</button><button role="menuitem" class="is-danger" data-delete-group="${esc(g.id)}">Excluir grupo</button></div>`:''}<button class="nxl-ag-mobile-expand nxl-ag-icon-button" ${preview?'disabled':''} data-open-group="${esc(g.id)}" aria-label="${open?'Recolher':'Expandir'} grupo ${esc(g.name)}" aria-expanded="${open}">${icon(open?'chevron-up':'chevron-down')}</button></div><div class="nxl-ag-group-summary"><span class="nxl-ag-counter is-good"><i></i>${c.operational} operacionais</span>${c.attention?`<span class="nxl-ag-counter is-attention"><i></i>${c.attention} em atenção</span>`:''}<span class="nxl-ag-desktop-arrow">${icon('chevron-right')}</span></div>${open&&!preview?`<div class="nxl-ag-mobile-sample"><p>Mostrando ${Math.min(3,list.length)} de ${list.length} bens</p>${list.slice().sort((a,b)=>Number(b.status!=='Operacional')-Number(a.status!=='Operacional')).slice(0,3).map(a=>`<button class="nxl-ag-sample-row" data-detail="${a.id}"><span><strong>${esc(a.name)}</strong><small>${esc(a.code||'Sem etiqueta')}</small><small>${esc(a.location)}</small></span>${badge(a.status)}${icon('chevron-right')}</button>`).join('')}${!list.length?'<p>Este grupo ainda não tem bens.</p>':''}<button class="nxl-ag-link" data-list-group="${esc(g.id)}">Ver ${list.length?list.length+' bens':'grupo completo'} ${icon('arrow-right')}</button></div>`:''}</article>`;}
function closeMenus(){document.querySelectorAll('.nxl-ag-group-menu').forEach(n=>n.hidden=true);document.querySelectorAll('[data-group-menu]').forEach(n=>n.setAttribute('aria-expanded','false'));}
function fillOptions(select,values,empty,value){select.innerHTML='<option value="">'+esc(empty)+'</option>'+values.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');select.value=value;}
function render(){if(!loaded)return;const s=current(),rows=filtered(),base=isGroup()?getGroup(view):data.assets,max=Math.max(1,Math.ceil(rows.length/s.size));s.page=Math.min(s.page,max);const overview=view==='home'&&!activeFilters();$('groups').hidden=!overview;$('list').hidden=overview||!rows.length;$('empty').hidden=overview||!!rows.length;$('title').textContent=overview?'Grupos':isGroup()?group(view).name:s.q?'Resultados no patrimônio':'Todos os bens';$('heading-icon').hidden=!isGroup();$('heading-icon').style.setProperty('--group-color',isGroup()?group(view).color:'#8754c7');$('heading-icon').innerHTML=isGroup()?icon(group(view).icon):'';$('heading-summary').innerHTML=overview?'<span>'+data.assets.length+' bens individuais</span>':isGroup()?summary(base):'<span>'+rows.length+' encontrados de '+data.assets.length+' bens</span>';$('edit-group').hidden=!canManage||!isGroup()||group(view).reserved;$('new-group').hidden=!canManage||isGroup();$('new-asset').hidden=!canManage;$('back').hidden=view==='home';root.dataset.assetView=isGroup()?'group':view;$('filter-note').hidden=isGroup()&&!activeFilters();
 $('search').value=s.q;$('search').placeholder=isGroup()?'Buscar nome ou código neste grupo':'Buscar nome ou código em todos os grupos';$('condition').value=s.condition;fillOptions($('type'),[...new Set(base.map(a=>a.type).filter(Boolean))].sort(),'Tipo',s.type);fillOptions($('location'),[...new Set(base.map(a=>a.location).filter(Boolean))].sort(),'Local',s.location);
 $('count-label').textContent=overview?'Abra um grupo para consultar os bens.':rows.length+' encontrados de '+base.length+(isGroup()?' bens neste grupo':' bens no patrimônio');$('global-search').hidden=!isGroup()||!s.q;$('clear').disabled=!activeFilters();$('footer-count').textContent=data.groups.length+' grupos · '+getGroup('ungrouped').length+' bens sem grupo';$('all').hidden=view==='all';
 if(overview)$('groups').innerHTML=groups().map(g=>groupCard(g)).join('');
 if(!overview){$('empty-title').textContent=activeFilters()?'Nenhum bem encontrado':'Este grupo está vazio';$('empty-copy').textContent=activeFilters()?'Confira os filtros ou amplie a busca para todo o patrimônio.':'Cadastre um bem neste grupo ou mova bens de outro grupo para cá.';$('empty-clear').hidden=!activeFilters();renderTable();renderPagination();}
}
function detailHTML(a){return `<div class="nxl-ag-detail-grid">${[['Código patrimonial',a.code||'Sem etiqueta'],['Tipo',a.type],['Grupo',group(a.groupId).name],['Localização',a.location],['Condição',a.status],['Responsável',a.responsible],['Quantidade','1 bem individual'],['Aquisição',date(a.acquired)],['Valor de aquisição',money(a.unitValue)],['Cadastrado em',date(a.createdAt)],['Última atualização',date(a.updatedAt)]].map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')}</div><h3>Descrição completa</h3><p class="nxl-ag-full-text">${esc(a.description||'Não registrado')}</p><h3>Observações</h3><p class="nxl-ag-full-text">${esc(a.notes||'Não registrado')}</p><h3>Ocorrências preservadas</h3><ol class="nxl-ag-history">${a.history.map(h=>`<li><strong>${esc(h.kind)}</strong><small>${esc(date(h.at))} · ${esc(h.responsible)}</small><p>${esc(h.description)}</p></li>`).join('')}</ol>`;}
