function openMove(ids=null){if(!canManage||!fresh)return;if(ids)selected=new Set(ids);if(!selected.size)return;$('move-summary').textContent='Mover '+selected.size+' '+(selected.size===1?'bem selecionado.':'bens selecionados.');$('move-codes').innerHTML=data.assets.filter(a=>selected.has(a.id)).map(a=>'<span>'+esc(a.code||a.name+' · sem etiqueta')+'</span>').join('');fillGroups($('move-target'),'ungrouped');const first=groups().find(g=>data.assets.some(a=>selected.has(a.id)&&(a.groupId||'ungrouped')!==g.id));if(first)$('move-target').value=first.id;$('move-error').hidden=true;updateMove();show('move-dialog');}
