on(modalHost,'cancel',e=>{if(busy)e.preventDefault();},true);
on(document,'visibilitychange',()=>{if(document.visibilityState==='visible')scheduleRefresh();});
on(window,'focus',scheduleRefresh);
// The real application owns global navigation, headers and dialogs. This leaf
// workspace manages only its own content and removes every listener on unmount.
const oldClickHandlers=[...modalHost.querySelectorAll('button')];
const documentClick=e=>{if(!e.target.closest('[data-group-menu],.nxl-ag-group-menu'))closeMenus();};
const documentKey=e=>{if(e.key==='Escape')closeMenus();if(e.target.closest('.nxl-ag-group-menu')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const choices=[...e.target.closest('.nxl-ag-group-menu').querySelectorAll('button')],i=choices.indexOf(document.activeElement);choices[(i+(e.key==='ArrowDown'?1:choices.length-1))%choices.length].focus();}};
on(document,'click',documentClick);on(document,'keydown',documentKey);
const viewport=matchMedia('(max-width:767px)');on(viewport,'change',()=>render());
