await refresh();if(disposed)return null;
try{realtime=options.supabase.channel('nexlab-assets-groups-'+options.profile.id+'-'+uuid()).on('postgres_changes',{event:'*',schema:'public',table:'assets'},scheduleRefresh).on('postgres_changes',{event:'*',schema:'public',table:'asset_groups'},scheduleRefresh).subscribe(status=>{realtimeState=status;if(!disposed)applyAccess();});}catch{realtimeState='';}

return {refresh:scheduleRefresh,openEditor:asset=>openAssetEditor(typeof asset==='string'?asset:asset.id),dispose};


